namespace ghidra.app.plugin.core.datamgr.actions;

using docking;
using docking.action;
using docking.action;
using docking.widgets.dialogs;
using docking.widgets.tree;
using docking.widgets.tree.support;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.util;
using ghidra.util.datastruct;
using ghidra.util.datastruct;

public class FindDataTypesBySizeAction : DockingAction {

	public static readonly string NAME = "Find Data Types by Size";

	private DataTypeManagerPlugin plugin;

	public FindDataTypesBySizeAction(DataTypeManagerPlugin plugin, string menuSubGroup) : this(plugin, NAME, menuSubGroup)
    {
	}

	FindDataTypesBySizeAction(DataTypeManagerPlugin plugin, string name, string menuSubGroup) : base(name, plugin.getName())
    {
		this.plugin = plugin;

		setMenuBarData(
			new MenuData(new string[] { name + "..." }, null, "VeryLast", -1, menuSubGroup));
		setHelpLocation(new HelpLocation("DataTypeManagerPlugin", "Find_Data_Types_By_Size"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {

		NumberRangeInputDialog inputDialog = new NumberRangeInputDialog(getName(), "Size(s)");
		inputDialog.setHelpLocation(getHelpLocation());
		if (!inputDialog.show()) {
			return;
		}

		SortedRangeList values = inputDialog.getValue();
		DataTypesProvider newProvider = plugin.createProvider();
		newProvider.setTitle(getName());
		DataTypeArchiveGTree tree = newProvider.getGTree();
		GTreeFilter filter = createFilter(values);
		tree.setFilterProvider(new SecondaryTreeFilterProvider(tree, filter));
		newProvider.setVisible(true);
	}

	protected GTreeFilter createFilter(SortedRangeList values) {
		return new SizeGTreeFilter(values);
	}

	private class SizeGTreeFilter : GTreeFilter {

		private SortedRangeList sizes;

		SizeGTreeFilter(SortedRangeList sizes) {
			this.sizes = sizes;
		}

		/* @Override */
		public bool showFilterMatches() {
			return true;
		}

		/* @Override */
		public bool acceptsNode(GTreeNode node) {
			if (!(node is DataTypeNode)) {
				return false;
			}
			DataTypeNode dataTypeNode = (DataTypeNode) node;
			DataType dt = dataTypeNode.getDataType();
			int length = dt.getLength();
			if (dt.isZeroLength()) {
				length = 0;
			}

			foreach (Range range in sizes) {
				if (range.contains(length)) {
					return true;
				}
			}

			return false;
		}
	}
}
